WITH posts_with_variance AS (
  SELECT id, title FROM posts WHERE title LIKE '%variance%' LIMIT 100
), bounty_votes AS (
  SELECT postid, userid, bountyamount FROM votes WHERE bountyamount = 50
)
SELECT u.displayname FROM posts_with_variance p JOIN bounty_votes bv ON p.id = bv.postid JOIN users u ON u.id = bv.userid LIMIT 1;
